      `;

      document.body.appendChild(this.container);

      const qContainer = this.container.querySelector("#hud-q-bars");
      this.qBars = [];
      ACTION_NAMES.forEach((name, i) => {
        const row = document.createElement("div");
        row.className = "q-bar-row";
        row.innerHTML = `
